// 绘制六维雷达图
function drawRadarChart() {
    const canvas = document.getElementById('radarChart');
    if (!canvas || !canvas.getContext) return;

    const ctx = canvas.getContext('2d');
    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const radius = Math.min(centerX, centerY) - 40;

    // 清空画布
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 获取当前属性值
    const attributes = [
        { name: '体质', value: parseInt(document.getElementById('con-val').textContent) || 0 },
        { name: '力量', value: parseInt(document.getElementById('str-val').textContent) || 0 },
        { name: '智力', value: parseInt(document.getElementById('int-val').textContent) || 0 },
        { name: 'AC', value: parseInt(document.getElementById('ac-val').textContent) || 0 },
        { name: '敏捷', value: parseInt(document.getElementById('dex-val').textContent) || 0 },
        { name: '魅力', value: parseInt(document.getElementById('cha-val').textContent) || 0 }
    ];

    const maxValue = 30; // 假设最大值为30
    const angleStep = (Math.PI * 2) / 6; // 六边形

    // 绘制背景网格
    ctx.strokeStyle = 'rgba(0, 255, 204, 0.2)';
    ctx.lineWidth = 1;

    // 绘制同心六边形（5层）
    for (let i = 1; i <= 5; i++) {
        ctx.beginPath();
        for (let j = 0; j < 6; j++) {
            const angle = j * angleStep - Math.PI / 2;
            const x = centerX + Math.cos(angle) * (radius * i / 5);
            const y = centerY + Math.sin(angle) * (radius * i / 5);

            if (j === 0) {
                ctx.moveTo(x, y);
            } else {
                ctx.lineTo(x, y);
            }
        }
        ctx.closePath();
        ctx.stroke();
    }

    // 绘制轴线
    ctx.strokeStyle = 'rgba(0, 255, 204, 0.3)';
    for (let i = 0; i < 6; i++) {
        const angle = i * angleStep - Math.PI / 2;
        ctx.beginPath();
        ctx.moveTo(centerX, centerY);
        ctx.lineTo(
            centerX + Math.cos(angle) * radius,
            centerY + Math.sin(angle) * radius
        );
        ctx.stroke();
    }

    // 绘制属性值多边形
    const dataPoints = [];

    // 先收集所有数据点
    for (let i = 0; i < 6; i++) {
        const angle = i * angleStep - Math.PI / 2;
        const value = attributes[i].value;
        const distance = (value / maxValue) * radius;
        const x = centerX + Math.cos(angle) * distance;
        const y = centerY + Math.sin(angle) * distance;
        dataPoints.push({ x, y });
    }

    // 绘制填充区域
    ctx.beginPath();
    ctx.fillStyle = 'rgba(0, 255, 204, 0.2)';
    ctx.strokeStyle = '#00ffcc';
    ctx.lineWidth = 2;

    dataPoints.forEach((point, index) => {
        if (index === 0) {
            ctx.moveTo(point.x, point.y);
        } else {
            ctx.lineTo(point.x, point.y);
        }
    });

    ctx.closePath(); // 关闭路径，连接最后一个点和第一个点
    ctx.fill();
    ctx.stroke();

    // 绘制数据点（发光效果）
    dataPoints.forEach(point => {
        // 外圈光晕
        ctx.beginPath();
        ctx.arc(point.x, point.y, 8, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(0, 255, 204, 0.3)';
        ctx.fill();

        // 中圈
        ctx.beginPath();
        ctx.arc(point.x, point.y, 5, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(0, 255, 204, 0.6)';
        ctx.fill();

        // 内圈实心点
        ctx.beginPath();
        ctx.arc(point.x, point.y, 3, 0, Math.PI * 2);
        ctx.fillStyle = '#00ffcc';
        ctx.fill();
    });

    // 绘制属性标签和数值
    ctx.font = '14px Consolas, monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    for (let i = 0; i < 6; i++) {
        const angle = i * angleStep - Math.PI / 2;
        const labelDistance = radius + 25;
        const x = centerX + Math.cos(angle) * labelDistance;
        const y = centerY + Math.sin(angle) * labelDistance;

        // 绘制属性名（带阴影效果）
        ctx.shadowColor = 'rgba(0, 255, 204, 0.8)';
        ctx.shadowBlur = 10;
        ctx.fillStyle = '#00ffcc';
        ctx.fillText(attributes[i].name, x, y);
        ctx.shadowBlur = 0;

        // 绘制属性值
        if (attributes[i].value > 0) {
            const valueDistance = (attributes[i].value / maxValue) * radius;
            const valueX = centerX + Math.cos(angle) * (valueDistance + 20);
            const valueY = centerY + Math.sin(angle) * (valueDistance + 20);

            // 值背景
            ctx.beginPath();
            ctx.arc(valueX, valueY, 12, 0, Math.PI * 2);
            ctx.fillStyle = 'rgba(255, 0, 128, 0.3)';
            ctx.fill();

            // 值文字
            ctx.fillStyle = '#ff0080';
            ctx.font = 'bold 12px Consolas, monospace';
            ctx.fillText(attributes[i].value, valueX, valueY);
        }
    }

    // 添加中心点装饰
    ctx.beginPath();
    ctx.arc(centerX, centerY, 3, 0, Math.PI * 2);
    ctx.fillStyle = '#ff0080';
    ctx.fill();
}

// 初始化
document.addEventListener('DOMContentLoaded', function() {
    // 初始化按钮状态
    updateButtons();

    // 如果初始在属性页，绘制雷达图
    if (document.getElementById('tab-attrs').classList.contains('active')) {
        drawRadarChart();
    }

    // 防止移动端双击缩放
    let lastTouchEnd = 0;
    document.addEventListener('touchend', function(event) {
        const now = Date.now();
        if (now - lastTouchEnd <= 300) {
            event.preventDefault();
        }
        lastTouchEnd = now;
    }, false);
});
</script>

