  <script>
    // 属性管理
    let attributeIncrements = {
      'constitution': 0,
      'strength': 0,
      'intelligence': 0,
      'ac': 0,
      'agility': 0,
      'charisma': 0
    };
    let totalPointsSpent = 0;

    // 标签切换
    function showTab(tabId) {
      document.querySelectorAll('.tab-content').forEach(content => {
        content.classList.remove('active');
      });
      document.querySelectorAll('.tab-button').forEach(button => {
        button.classList.remove('active');
      });

      document.getElementById('content-' + tabId).classList.add('active');
      document.getElementById('tab-' + tabId).classList.add('active');

      // 如果切换到属性页，更新六维图
      if (tabId === 'attributes') {
        setTimeout(updateRadarChart, 100);
      }
    }

    // 分配属性点
    function allocatePoint(attributeType) {
      let pointsElement = document.getElementById('attribute-points');
      let availablePoints = parseInt(pointsElement.textContent);

      if (availablePoints <= 0) {
        alert('没有可用属性点！');
        return;
      }

      let valueElement = document.getElementById(attributeType + '-value');
      let currentValue = parseInt(valueElement.textContent);
      valueElement.textContent = currentValue + 1;

      attributeIncrements[attributeType]++;
      document.getElementById(attributeType + '-increment').textContent = `(+${attributeIncrements[attributeType]})`;

      availablePoints--;
      totalPointsSpent++;
      pointsElement.textContent = availablePoints;
      document.getElementById('points-spent').textContent = `(已分配: ${totalPointsSpent})`;

      updateButtonStates();
      updateRadarChart();

      let commandText = `${getAttributeLabel(attributeType)}分配属性点+1，`;
      let textarea = document.getElementById('command-text');
      textarea.value += commandText;
    }

    // 获取属性标签
    function getAttributeLabel(attributeType) {
      const labels = {
        'constitution': '体质',
        'strength': '力量',
        'intelligence': '智力',
        'ac': 'AC',
        'agility': '敏捷',
        'charisma': '魅力'
      };
      return labels[attributeType] || attributeType;
    }

    // 更新按钮状态
    function updateButtonStates() {
      let availablePoints = parseInt(document.getElementById('attribute-points').textContent);
      document.querySelectorAll('.attr-btn').forEach(btn => {
        if (availablePoints <= 0) {
          btn.classList.add('disabled');
          btn.disabled = true;
        } else {
          btn.classList.remove('disabled');
          btn.disabled = false;
        }
      });
    }

    // 复制到剪贴板
    function copyToClipboard() {
      let textarea = document.getElementById('command-text');
      if (!textarea.value) {
        alert('没有可复制的内容！');
        return;
      }

      textarea.select();
      document.execCommand('copy');

      let originalValue = textarea.value;
      textarea.value = '已复制!';
      setTimeout(() => {
        textarea.value = originalValue;
      }, 1000);
    }

    // 统计命令
    function summarizeCommands() {
      let textarea = document.getElementById('command-text');
      let currentText = textarea.value.trim();

      if (!currentText) {
        alert('没有可统计的内容！');
        return;
      }

      const commands = currentText.split('，').map(cmd => cmd.trim()).filter(cmd => cmd.length > 0);
      const summary = {};
      const commandRegex = /^(体质|力量|智力|AC|敏捷|魅力)分配属性点\+(\d+)$/;

      for (const command of commands) {
        const match = command.match(commandRegex);
        if (match) {
          const attributeName = match[1];
          const points = parseInt(match[2]);
          summary[attributeName] = (summary[attributeName] || 0) + points;
        }
      }

      let newCommandTextParts = [];
      const attributeOrder = ['体质', '力量', '智力', 'AC', '敏捷', '魅力'];

      for (const attr of attributeOrder) {
        if (summary[attr] > 0) {
          newCommandTextParts.push(`${attr}分配属性点+${summary[attr]}`);
        }
      }

      textarea.value = newCommandTextParts.join('，') + '，';
    }

    // 清空并返还点数
    function resetAllPoints() {
      if (totalPointsSpent === 0) {
        alert('没有已分配的属性点！');
        return;
      }

      if (!confirm(`确定要清空所有已分配的属性点吗？\n将返还 ${totalPointsSpent} 点属性点。`)) {
        return;
      }

      for (let attr in attributeIncrements) {
        if (attributeIncrements[attr] > 0) {
          let valueElement = document.getElementById(attr + '-value');
          let currentValue = parseInt(valueElement.textContent);
          valueElement.textContent = currentValue - attributeIncrements[attr];

          attributeIncrements[attr] = 0;
          document.getElementById(attr + '-increment').textContent = '(+0)';
        }
      }

      let pointsElement = document.getElementById('attribute-points');
      let currentPoints = parseInt(pointsElement.textContent);
      pointsElement.textContent = currentPoints + totalPointsSpent;

      totalPointsSpent = 0;
      document.getElementById('points-spent').textContent = '(已分配: 0)';
      document.getElementById('command-text').value = '';

      updateButtonStates();
      updateRadarChart();

      alert('属性点已全部返还！');
    }

    // 绘制六维图
    function updateRadarChart() {
      const canvas = document.getElementById('radarChart');
      if (!canvas) return;

      const ctx = canvas.getContext('2d');
      const centerX = canvas.width / 2;
      const centerY = canvas.height / 2;
      const radius = 100;

      // 清空画布
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // 绘制背景网格
      ctx.strokeStyle = 'rgba(0, 255, 204, 0.1)';
      ctx.lineWidth = 1;

      // 绘制六边形网格
      for (let i = 1; i <= 5; i++) {
        ctx.beginPath();
        for (let j = 0; j < 6; j++) {
          const angle = (Math.PI / 3) * j - Math.PI / 2;
          const x = centerX + (radius * i / 5) * Math.cos(angle);
          const y = centerY + (radius * i / 5) * Math.sin(angle);
          if (j === 0) {
            ctx.moveTo(x, y);
          } else {
            ctx.lineTo(x, y);
          }
        }
        ctx.closePath();
        ctx.stroke();
      }

      // 绘制轴线
      ctx.strokeStyle = 'rgba(0, 255, 204, 0.3)';
      for (let i = 0; i < 6; i++) {
        const angle = (Math.PI / 3) * i - Math.PI / 2;
        ctx.beginPath();
        ctx.moveTo(centerX, centerY);
        ctx.lineTo(
          centerX + radius * Math.cos(angle),
          centerY + radius * Math.sin(angle)
        );
        ctx.stroke();
      }

      // 获取属性值
      const attributes = [
        parseInt(document.getElementById('constitution-value').textContent),
        parseInt(document.getElementById('strength-value').textContent),
        parseInt(document.getElementById('intelligence-value').textContent),
        parseInt(document.getElementById('ac-value').textContent),
        parseInt(document.getElementById('agility-value').textContent),
        parseInt(document.getElementById('charisma-value').textContent)
      ];

      // 绘制数据区域
      ctx.fillStyle = 'rgba(0, 255, 204, 0.2)';
      ctx.strokeStyle = '#00ffcc';
      ctx.lineWidth = 2;
      ctx.beginPath();

      for (let i = 0; i < 6; i++) {
        const angle = (Math.PI / 3) * i - Math.PI / 2;
        const value = Math.min(attributes[i] / 20, 1); // 假设最大值为20
        const x = centerX + radius * value * Math.cos(angle);
        const y = centerY + radius * value * Math.sin(angle);

        if (i === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      }

      ctx.closePath();
      ctx.fill();
      ctx.stroke();

      // 绘制数据点
      ctx.fillStyle = '#ff0080';
      for (let i = 0; i < 6; i++) {
        const angle = (Math.PI / 3) * i - Math.PI / 2;
        const value = Math.min(attributes[i] / 20, 1);
        const x = centerX + radius * value * Math.cos(angle);
        const y = centerY + radius * value * Math.sin(angle);

        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
      }

      // 绘制标签
      ctx.fillStyle = '#00ffcc';
      ctx.font = '12px Consolas';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';

      const labels = ['体质', '力量', '智力', 'AC', '敏捷', '魅力'];
      for (let i = 0; i < 6; i++) {
        const angle = (Math.PI / 3) * i - Math.PI / 2;
        const x = centerX + (radius + 20) * Math.cos(angle);
        const y = centerY + (radius + 20) * Math.sin(angle);
        ctx.fillText(labels[i], x, y);

        // 显示数值
        const valueX = centerX + (radius + 35) * Math.cos(angle);
        const valueY = centerY + (radius + 35) * Math.sin(angle);
        ctx.fillStyle = '#ffffff';
        ctx.fillText(attributes[i], valueX, valueY);
        ctx.fillStyle = '#00ffcc';
      }
    }

