  <script>
    let currentLayer = null;

    function toggleLayer(layer) {
      const detailsContainer = document.getElementById('layer-details');
      const allZones = document.querySelectorAll('.zone-container');
      const targetZone = document.getElementById(layer + '-zones');

      // 如果点击的是当前展开的层级，则收起
      if (currentLayer === layer) {
        detailsContainer.style.display = 'none';
        allZones.forEach(zone => zone.style.display = 'none');
        currentLayer = null;

        // 更新所有卡片的提示文字
        document.querySelectorAll('.layer-card').forEach(card => {
          const hint = card.querySelector('div:last-child');
          if (hint) hint.textContent = '▶ 点击展开';
        });
        return;
      }

      // 隐藏所有分区
      allZones.forEach(zone => zone.style.display = 'none');

      // 显示选中的分区
      detailsContainer.style.display = 'block';
      targetZone.style.display = 'block';
      currentLayer = layer;

      // 更新卡片提示文字
      document.querySelectorAll('.layer-card').forEach((card, index) => {
        const hint = card.querySelector('div:last-child');
        if (hint) {
          const layerNames = ['top', 'middle', 'lower', 'bottom', 'outer'];
          hint.textContent = layerNames[index] === layer ? '▼ 点击收起' : '▶ 点击展开';
        }
      });

      // 平滑滚动到详情区域（移动端优化）
      setTimeout(() => {
        detailsContainer.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }, 100);
    }

    // 添加触摸事件优化
    document.addEventListener('DOMContentLoaded', function() {
      // 防止双击缩放
      let lastTouchEnd = 0;
      document.addEventListener('touchend', function(event) {
                const now = Date.now();
        if (now - lastTouchEnd <= 300) {
          event.preventDefault();
        }
        lastTouchEnd = now;
      }, false);

      // 优化滚动性能
      let ticking = false;
      function updateScrolling() {
        ticking = false;
      }

      function requestTick() {
        if (!ticking) {
          requestAnimationFrame(updateScrolling);
          ticking = true;
        }
      }

      window.addEventListener('scroll', requestTick, { passive: true });
    });
  </script>
</details>
