    text-align: center;
    margin: 10px 0;
}

.sys span {
    background: #d9d9d9;
    color: #888;
    padding: 2px 8px;
    border-radius: 3px;
    font-size: 12px;
}

/* 时间 */
.time {
    text-align: center;
    margin: 10px 0;
    color: #999;
    font-size: 12px;
}

/* 底部输入区 */
.footer {
    padding: 8px 10px;
    background: #F5F5F5;
    display: flex;
    align-items: center;
    border-top: 1px solid #E6E6E6;
    flex-shrink: 0;
}

.plus {
    font-size: 24px;
    color: #7F7F7F;
    margin-right: 10px;
