    <style>
        @import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@400;700;900&display=swap');

        * {
            box-sizing: border-box;
            -webkit-tap-highlight-color: transparent;
        }

        body {
            font-family: 'Orbitron', 'Microsoft YaHei', monospace;
            background-color: #000000;
            margin: 0;
            padding: 10px;
            min-height: 100vh;
            overflow-x: hidden;
            color: #00ffcc;
            background-image: 
                radial-gradient(circle at 20% 50%, rgba(0, 255, 204, 0.1) 0%, transparent 50%),
                radial-gradient(circle at 80% 80%, rgba(255, 0, 128, 0.1) 0%, transparent 50%);
        }

        .container {
            max-width: 900px;
            margin: 0 auto;
            background: linear-gradient(135deg, #16213e 0%, #0f0f1e 100%);
            padding: 20px;
            border-radius: 15px;
            box-shadow: 0 0 30px rgba(0,255,204,0.3);
            border: 1px solid #00ffcc;
            position: relative;
        }

        /* 赛博朋克装饰 */
        .container::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            height: 2px;
            background: linear-gradient(90deg, transparent, #00ffcc, transparent);
            animation: scan 3s linear infinite;
        }

        @keyframes scan {
            0% { transform: translateX(-100%); }
            100% { transform: translateX(100%); }
        }

        /* 标题 */
        .header {
            text-align: center;
            color: #00ffcc;
            margin-bottom: 20px;
            padding-bottom: 15px;
            border-bottom: 1px solid rgba(0,255,204,0.3);
        }

        .header h1 {
            font-size: 28px;
            margin: 0;
            text-shadow: 0 0 20px rgba(0,255,204,0.8);
            letter-spacing: 3px;
            font-weight: 900;
        }

        .header p {
            font-size: 14px;
            color: #ff0080;
            margin: 5px 0 0 0;
            letter-spacing: 2px;
        }

        /* 分页系统 */
        .page {
            display: none;
            animation: fadeIn 0.3s ease;
        }

        .page.active {
            display: block;
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        /* 进度指示器 */
        .progress-bar {
            display: flex;
            justify-content: center;
            margin-bottom: 25px;
            gap: 15px;
            position: relative;
            flex-wrap: wrap;
        }

        .progress-bar::before {
            content: '';
            position: absolute;
            top: 15px;
            left: 10%;
            right: 10%;
            height: 1px;
            background: rgba(0,255,204,0.3);
            z-index: 0;
        }

        .progress-step {
            position: relative;
            z-index: 1;
            text-align: center;
            cursor: pointer;
        }

        .progress-dot {
            width: 30px;
            height: 30px;
            background: rgba(0,0,0,0.8);
            border: 1px solid rgba(0,255,204,0.3);
            border-radius: 50%;
            margin: 0 auto 5px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 12px;
            color: #666;
            transition: all 0.3s ease;
        }

        .progress-step.active .progress-dot {
            background: #00ffcc;
            border-color: #00ffcc;
            color: #000;
            box-shadow: 0 0 20px rgba(0,255,204,0.8);
        }

        .progress-step.completed .progress-dot {
            background: #ff0080;
            border-color: #ff0080;
            color: #000;
        }

        .progress-label {
            font-size: 11px;
            color: #666;
            max-width: 60px;
        }

        .progress-step.active .progress-label,
        .progress-step.completed .progress-label {
            color: #00ffcc;
        }

        /* 页面导航 */
        .page-nav {
            display: flex;
            justify-content: space-between;
            margin-top: 25px;
            padding-top: 15px;
            border-top: 1px solid rgba(0,255,204,0.3);
            gap: 15px;
