        }

        .page-button:active {
            transform: translateY(0);
        }

        .page-button:disabled {
            opacity: 0.5;
            cursor: not-allowed;
            transform: none;
        }

        /* 世界观内容样式 */
        .lore-content {
            background: rgba(0,0,0,0.6);
