        <!-- 页面9: 完成 -->
        <div id="page-9" class="page">
            <h2 style="text-align:center;color:#00ffcc;margin-bottom:20px;">角色创建完成</h2>

            <textarea id="output" class="output-area" readonly>角色信息生成中...</textarea>

            <div class="control-buttons">
