    <!-- 通知提示 -->
    <div id="notification" class="notification"></div>

    <script>
        // 全局变量
        let currentPage = 1;
        const totalPages = 9;
        let remainingPoints = 20;

        // 角色数据
        let characterData = {
            race: '',
            job: '',
            faction: '',
            assistant: '',
            attributes: {
                con: 1,
                str: 1,
                int: 1,
                ac: 0,
                dex: 1,
                cha: 1
            },
            raceBonus: {
                con: 0,
                str: 0,
                int: 0,
                ac: 0,
                dex: 0,
                cha: 0
            },
            name: '',
            age: '',
            appearance: '',
            background: '',
            equipment: '',
            items: '',
            bag: '',
            assets: '',
            skills: '',
            story: ''
        };

        // 页面导航
        function navigatePage(direction) {
            if (direction === 'next' && currentPage < totalPages) {
                if (canProceed()) {
                    currentPage++;
                } else {
                    showNotification('请先完成当前页面的选择！');
                    return;
                }
            } else if (direction === 'prev' && currentPage > 1) {
                currentPage--;
            }

            showPage(currentPage);
        }

        // 检查是否可以进入下一页
        function canProceed() {
            switch(currentPage) {
                case 3: // 种族选择
                    return characterData.race !== '' || document.getElementById('custom-race').value.trim() !== '';
                case 4: // 职业选择
                    return characterData.job !== '' || document.getElementById('custom-job').value.trim() !== '';
                case 5: // 势力选择
                    return characterData.faction !== '' || document.getElementById('custom-faction').value.trim() !== '';
                case 6: // 助手选择
                    return characterData.assistant !== '';
                default:
                    return true;
            }
        }

        // 显示页面
        function showPage(pageNum) {
            // 隐藏所有页面
            document.querySelectorAll('.page').forEach(page => {
                page.classList.remove('active');
            });

            // 显示目标页面
            document.getElementById(`page-${pageNum}`).classList.add('active');

            // 更新进度条
            updateProgress(pageNum);

            // 更新导航按钮
            updateNavButtons();
        }

        // 更新进度条
        function updateProgress(step) {
            document.querySelectorAll('.progress-step').forEach((el, index) => {
                if (index + 1 < step) {
                    el.classList.add('completed');
                    el.classList.remove('active');
                } else if (index + 1 === step) {
                    el.classList.add('active');
                    el.classList.remove('completed');
                } else {
                    el.classList.remove('active', 'completed');
                }
            });
        }

        // 更新导航按钮
        function updateNavButtons() {
            const prevButtons = document.querySelectorAll('.page-prev');
            const nextButtons = document.querySelectorAll('.page-next');

            prevButtons.forEach(btn => {
                btn.disabled = currentPage === 1;
            });

            nextButtons.forEach(btn => {
                if (currentPage === totalPages) {
                    btn.disabled = true;
                } else {
                    // 检查是否可以进入下一页
                    btn.disabled = false;
                }
            });
        }

        // 属性修改
        function changeAttr(attr, value) {
            const newValue = characterData.attributes[attr] + value;

            // AC可以是负数，其他属性最小为0
            const minValue = attr === 'ac' ? -10 : 0;

            if (value > 0 && remainingPoints >= value && newValue <= 30) {
                characterData.attributes[attr] = newValue;
                remainingPoints -= value;
            } else if (value < 0 && newValue >= minValue) {
                characterData.attributes[attr] = newValue;
                remainingPoints -= value; // 减去负数等于加
            }

            updateAttrDisplay();
        }

        // 更新属性显示
        function updateAttrDisplay() {
            document.getElementById('remaining-points').textContent = remainingPoints;

            // 显示基础属性 + 种族加成
            const totalCon = characterData.attributes.con + characterData.raceBonus.con;
            const totalStr = characterData.attributes.str + characterData.raceBonus.str;
            const totalInt = characterData.attributes.int + characterData.raceBonus.int;
            const totalAc = characterData.attributes.ac + characterData.raceBonus.ac;
            const totalDex = characterData.attributes.dex + characterData.raceBonus.dex;
            const totalCha = characterData.attributes.cha + characterData.raceBonus.cha;

            document.getElementById('attr-con').textContent = totalCon;
            document.getElementById('attr-str').textContent = totalStr;
            document.getElementById('attr-int').textContent = totalInt;
            document.getElementById('attr-ac').textContent = totalAc;
            document.getElementById('attr-dex').textContent = totalDex;
            document.getElementById('attr-cha').textContent = totalCha;

            // 更新生命值
            const health = 20 + totalCon * 5;
            document.getElementById('health-value').textContent = health;

            // 更新按钮状态
            document.querySelectorAll('.attr-button').forEach(btn => {
                const text = btn.textContent;
                if (text.includes('+')) {
                    const cost = parseInt(text.replace('+', ''));
                    btn.disabled = remainingPoints < cost;
                }
            });
        }

        // 获取种族特性
        function getRaceTraits(race) {
            const traits = {
                '人类': '体质+2，魅力+1',
                '精灵': '敏捷+2，智力+2，魅力+4',
                '龙裔': '全属性+2',
                '矮人': '智力+2，力量+2',
                '兽人': '力量+2，敏捷+2，魅力+1',
                '吸血鬼': '火/雷伤害+10，吸血回复25%生命值，溢出转护盾',
                '恶魔': '火属性伤害+10',
                '魔鬼': '智力+2，魅力+1',
                '巨人': '力量+4'
            };
            return traits[race] || '无特殊特性';
        }

        // 应用种族加成
        function applyRaceBonus(race) {
            // 重置种族加成
            characterData.raceBonus = {
                con: 0,
                str: 0,
                int: 0,
                ac: 0,
                dex: 0,
                cha: 0
            };

            switch(race) {
                case '人类':
                    characterData.raceBonus.con = 2;
                    characterData.raceBonus.cha = 1;
                    break;
                case '精灵':
                    characterData.raceBonus.dex = 2;
                    characterData.raceBonus.int = 2;
                    characterData.raceBonus.cha = 4;
                    break;
                case '龙裔':
                    characterData.raceBonus.con = 2;
                    characterData.raceBonus.str = 2;
                    characterData.raceBonus.int = 2;
                    characterData.raceBonus.ac = 2;
                    characterData.raceBonus.dex = 2;
                    characterData.raceBonus.cha = 2;
                    break;
                case '矮人':
                    characterData.raceBonus.int = 2;
                    characterData.raceBonus.str = 2;
                    break;
                case '兽人':
                    characterData.raceBonus.str = 2;
                    characterData.raceBonus.dex = 2;
                    characterData.raceBonus.cha = 1;
                    break;
                case '吸血鬼':
                    // 特殊能力，不加属性
                    break;
                case '恶魔':
                    // 特殊能力，不加属性
                    break;
                case '魔鬼':
                    characterData.raceBonus.int = 2;
                    characterData.raceBonus.cha = 1;
                    break;
                case '巨人':
                    characterData.raceBonus.str = 4;
                    break;
            }

            updateAttrDisplay();
        }

        // 生成角色
function generateCharacter() {
    // 获取角色详情
    characterData.name = document.getElementById('char-name').value || '无名氏';
    characterData.age = document.getElementById('char-age').value || '未知';
    characterData.appearance = document.getElementById('char-appearance').value || '普通外貌';
