    // 获取最终的种族、职业、势力
    const finalRace = characterData.race || document.getElementById('custom-race').value.trim();
    const finalJob = characterData.job || document.getElementById('custom-job').value.trim();
    const finalFaction = characterData.faction || document.getElementById('custom-faction').value.trim();

    // 计算最终属性
    const finalCon = characterData.attributes.con + characterData.raceBonus.con;
    const finalStr = characterData.attributes.str + characterData.raceBonus.str;
    const finalInt = characterData.attributes.int + characterData.raceBonus.int;
    const finalAc = characterData.attributes.ac + characterData.raceBonus.ac;
    const finalDex = characterData.attributes.dex + characterData.raceBonus.dex;
    const finalCha = characterData.attributes.cha + characterData.raceBonus.cha;

    const health = 20 + finalCon * 5;

    // 生成输出文本
    let output = `<名字>${characterData.name}</名字>\n`;
    output += `<年龄>${characterData.age}</年龄>\n`;
