    output += `<装备>${characterData.equipment}</装备>\n`;
    output += `<道具>${characterData.items}</道具>\n`;
    output += `<包>${characterData.bag}</包>\n`;
    output += `<资产>${characterData.assets}</资产>\n`;
    output += `<生命值>${health}/${health}</生命值>\n`;
    output += `<经验值>0/100</经验值>\n`;
    output += `<属性点>${remainingPoints}</属性点>\n`;
    output += `<体质>${finalCon}</体质>\n`;
    output += `<力量>${finalStr}</力量>\n`;
    output += `<智力>${finalInt}</智力>\n`;
    output += `<AC>${finalAc}</AC>\n`;
    output += `<敏捷>${finalDex}</敏捷>\n`;
    output += `<魅力>${finalCha}</魅力>\n`;
    output += `<种族特性>${getRaceTraits(finalRace)}</种族特性>\n`;

    // 处理技能
    if (characterData.skills && characterData.skills !== '空') {
        output += `<技能>${characterData.skills}</技能>\n`;
    } else {
        output += `<技能>空</技能>\n`;
    }

    output += `<buff>无</buff>\n`;
    output += `<未学习>无</未学习>\n`;
    output += `<NPC>无</NPC>\n`;
    output += `<助手>${characterData.assistant}</助手>\n`;
    // 删除了时间、玩家位置、可前往位置、地图这四行
    output += `\n【开局故事】\n${characterData.story}`;

    document.getElementById('output').value = output;
    showNotification('角色生成成功！');
}


