    justify-content: center;
    gap: 10px;
    margin-bottom: 20px;
    flex-wrap: wrap;
}

.nav-btn {
    background: linear-gradient(135deg, rgba(0,255,204,0.1) 0%, rgba(255,0,128,0.1) 100%);
    border: 1px solid #00ffcc;
    border-radius: 8px;
    padding: 10px 20px;
    color: #00ffcc;
    font-size: 14px;
    font-weight: bold;
    cursor: pointer;
    transition: all 0.3s ease;
    font-family: inherit;
    flex: 1;
    min-width: 100px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
}

.nav-btn:hover {
    background: linear-gradient(135deg, rgba(0,255,204,0.2) 0%, rgba(255,0,128,0.2) 100%);
    transform: translateY(-2px);
    box-shadow: 0 5px 15px rgba(0,255,204,0.3);
}

.nav-btn.active {
    background: linear-gradient(135deg, rgba(0,255,204,0.3) 0%, rgba(255,0,128,0.3) 100%);
    box-shadow: 0 0 20px rgba(0,255,204,0.5);
}

/* 页面容器 */
.page {
    display: none;
    background: linear-gradient(135deg, #16213e 0%, #0f0f1e 100%);
    border: 1px solid #00ffcc;
    border-radius: 12px;
    padding: 25px;
    box-shadow: 0 0 30px rgba(0,255,204,0.2);
}

.page.active {
    display: block;
}

/* 对话框样式 */
.dialog-box {
    background: linear-gradient(135deg, #0a0f1b 0%, #1a1f2e 100%);
    border: 1px solid #00ffcc;
    border-radius: 10px;
    padding: 25px;
    position: relative;
    box-shadow: 0 0 20px rgba(0,255,204,0.2);
}

.dialog-header {
    position: absolute;
    top: -15px;
    left: 50%;
    transform: translateX(-50%);
    background: linear-gradient(135deg, #00ffcc 0%, #00ccff 100%);
    padding: 5px 20px;
    border-radius: 20px;
    color: #0a0f1b;
    font-size: 12px;
    font-weight: bold;
    box-shadow: 0 0 15px rgba(0,255,204,0.6);
}

.dialog-content {
    color: #e0e0e0;
    font-size: 16px;
    line-height: 1.8;
    padding: 20px;
    background: rgba(0,255,204,0.05);
    border-radius: 8px;
    margin-top: 10px;
    border: 1px solid rgba(0,255,204,0.1);
    white-space: pre-wrap;
}

.dialog-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 20px;
    padding-top: 20px;
    border-top: 1px solid rgba(0,255,204,0.3);
}

.dialog-seal {
    width: 45px;
    height: 45px;
    background: linear-gradient(135deg, #ff0080 0%, #ff4d94 100%);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-weight: bold;
    transform: rotate(-15deg);
    box-shadow: 0 0 15px rgba(255,0,128,0.5);
}

.dialog-date {
    color: #00ccff;
    font-size: 14px;
}

/* 地图样式 */
.map-header {
    text-align: center;
    padding: 20px;
    background: linear-gradient(135deg, rgba(0,255,204,0.1) 0%, rgba(255,0,128,0.1) 100%);
    border-radius: 10px;
    margin-bottom: 25px;
    border: 1px solid rgba(0,255,204,0.3);
}

.map-title {
    font-size: 22px;
    color: #00ffcc;
    text-shadow: 0 0 20px rgba(0,255,204,0.8);
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
}

.city-info {
    background: rgba(0,0,0,0.6);
    border: 1px solid rgba(0,255,204,0.3);
    border-radius: 8px;
    padding: 15px;
    margin-bottom: 20px;
}

.city-status {
    color: #ff0080;
    font-size: 14px;
    margin-bottom: 8px;
    display: flex;
    align-items: center;
    gap: 8px;
}

.city-details {
    color: #ffffff;
    font-size: 13px;
    line-height: 1.6;
}

.layer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 12px;
    margin-bottom: 20px;
}

.layer-card {
    background: rgba(0,255,204,0.1);
    border: 1px solid rgba(0,255,204,0.3);
    border-radius: 10px;
    padding: 15px;
    cursor: pointer;
    transition: all 0.3s ease;
    text-align: center;
}

.layer-card:hover {
    background: rgba(0,255,204,0.2);
    transform: translateY(-3px);
    box-shadow: 0 8px 20px rgba(0,255,204,0.4);
    border-color: #00ffcc;
}

.layer-name {
    color: #00ffcc;
    font-size: 18px;
    font-weight: bold;
    margin-bottom: 5px;
}

.layer-subtitle {
    color: #ffffff;
    font-size: 13px;
    opacity: 0.9;
    margin-bottom: 3px;
}

.layer-height {
    color: #ff0080;
    font-size: 12px;
    margin-bottom: 8px;
}

.layer-hint {
    color: #ffffff;
    font-size: 11px;
    opacity: 0.7;
}

.zone-details {
    display: none;
    background: rgba(0,0,0,0.7);
    border: 1px solid rgba(0,255,204,0.3);
    border-radius: 10px;
    padding: 20px;
    margin-top: 20px;
}

.zone-details.active {
    display: block;
}

.zone-title {
    color: #ff0080;
    font-size: 18px;
    margin-bottom: 15px;
    text-shadow: 0 0 10px rgba(255,0,128,0.8);
}

.zone-item {
    background: rgba(0,0,0,0.5);
    border: 1px solid rgba(0,255,204,0.2);
    border-radius: 8px;
    padding: 12px;
    margin-bottom: 10px;
}

.zone-item-title {
    color: #00ffcc;
    font-size: 15px;
    font-weight: bold;
    margin-bottom: 5px;
}

.zone-item-desc {
    color: #ffffff;
    font-size: 13px;
    line-height: 1.5;
}

/* 状态栏样式 */
.status-header {
    text-align: center;
    margin-bottom: 25px;
}

.char-name {
    font-size: 28px;
    color: #00ffcc;
    text-shadow: 0 0 25px rgba(0,255,204,0.8);
    margin-bottom: 5px;
}

.char-subtitle {
    color: #ff0080;
    font-size: 13px;
    text-transform: uppercase;
    letter-spacing: 3px;
}

.tab-nav {
    display: flex;
    justify-content: center;
    gap: 8px;
    margin-bottom: 20px;
    flex-wrap: wrap;
}

.tab-btn {
    background: linear-gradient(135deg, rgba(0,255,204,0.1) 0%, rgba(255,0,128,0.1) 100%);
    border: 1px solid rgba(0,255,204,0.5);
    border-radius: 6px;
    padding: 8px 16px;
    color: #00ffcc;
    font-size: 13px;
    font-weight: bold;
    cursor: pointer;
    transition: all 0.3s ease;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.tab-btn:hover {
    background: linear-gradient(135deg, rgba(0,255,204,0.2) 0%, rgba(255,0,128,0.2) 100%);
    transform: translateY(-2px);
    box-shadow: 0 5px 15px rgba(0,255,204,0.4);
}

.tab-btn.active {
    background: linear-gradient(135deg, rgba(0,255,204,0.3) 0%, rgba(255,0,128,0.3) 100%);
    box-shadow: 0 0 20px rgba(0,255,204,0.6);
    border-color: #00ffcc;
}

.tab-content {
    display: none;
    background: rgba(0,0,0,0.6);
    border: 1px solid rgba(0,255,204,0.3);
    border-radius: 10px;
    padding: 20px;
}

.tab-content.active {
    display: block;
}

.info-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 12px;
    margin-bottom: 20px;
}

.info-item {
    background: rgba(0,255,204,0.05);
