}

.info-value {
    color: #ffffff;
    font-size: 15px;
    font-weight: bold;
}

.stat-bar {
    margin-bottom: 15px;
}

.stat-label {
    color: #00ffcc;
    font-size: 13px;
    text-transform: uppercase;
    margin-bottom: 5px;
