    display: flex;
    align-items: center;
    justify-content: flex-end;
    padding-right: 10px;
}

.bar-fill.hp {
    background: linear-gradient(90deg, #ff0080 0%, #ff4d94 100%);
}

.bar-fill.exp {
    background: linear-gradient(90deg, #00ffcc 0%, #00ccff 100%);
}

.bar-text {
    color: #ffffff;
    font-size: 11px;
    font-weight: bold;
    text-shadow: 0 0 5px rgba(0,0,0,0.8);
}

.attr-list {
    margin-bottom: 20px;
}

.attr-header {
    text-align: center;
    margin-bottom: 20px;
    padding-bottom: 15px;
    border-bottom: 1px solid rgba(0,255,204,0.3);
}

.points-display {
    color: #ff0080;
    font-size: 24px;
    font-weight: bold;
}

.attr-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px;
    background: rgba(0,255,204,0.05);
    border: 1px solid rgba(0,255,204,0.2);
    border-radius: 6px;
    margin-bottom: 10px;
}

.attr-name {
    color: #00ffcc;
    font-size: 15px;
    width: 60px;
}

.attr-value {
    color: #ffffff;
    font-size: 20px;
    font-weight: bold;
    margin: 0 15px;
}

.attr-increment {
    color: #ff0080;
    font-size: 13px;
    margin-right: auto;
}

.attr-btn {
    width: 32px;
    height: 32px;
    background: linear-gradient(135deg, #00ffcc 0%, #00ccff 100%);
    border: none;
    border-radius: 50%;
    color: #0a0a0a;
    font-size: 18px;
    font-weight: bold;
    cursor: pointer;
    transition: all 0.3s ease;
}

.attr-btn:hover:not(:disabled) {
    transform: scale(1.15);
    box-shadow: 0 0 20px rgba(0,255,204,0.8);
}

.attr-btn:disabled {
    opacity: 0.3;
    cursor: not-allowed;
}

.command-area {
    margin-top: 20px;
    padding-top: 20px;
    border-top: 1px solid rgba(0,255,204,0.3);
}

.command-textarea {
    width: 100%;
    min-height: 80px;
    background: rgba(0,0,0,0.8);
    border: 1px solid rgba(0,255,204,0.5);
    border-radius: 6px;
    color: #00ffcc;
    padding: 10px;
    font-family: inherit;
    font-size: 13px;
    resize: vertical;
}

.command-buttons {
    display: flex;
    gap: 10px;
    margin-top: 10px;
}

.cmd-btn {
    flex: 1;
    padding: 8px 16px;
    background: linear-gradient(135deg, rgba(0,255,204,0.2) 0%, rgba(255,0,128,0.2) 100%);
    border: 1px solid rgba(0,255,204,0.5);
    border-radius: 6px;
    color: #00ffcc;
    font-size: 13px;
    font-weight: bold;
    cursor: pointer;
    transition: all 0.3s ease;
    text-transform: uppercase;
}

.cmd-btn:hover {
    background: linear-gradient(135deg, rgba(0,255,204,0.3) 0%, rgba(255,0,128,0.3) 100%);
    box-shadow: 0 5px 15px rgba(0,255,204,0.5);
}

/* 响应式设计 */
@media (max-width: 768px) {
    body {
        padding: 5px;
    }

    .nav-btn {
        min-width: 80px;
        font-size: 13px;
        padding: 8px 15px;
    }

    .page {
        padding: 15px;
    }

    .layer-grid {
        grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
    }

    .info-grid {
        grid-template-columns: 1fr;
    }

    .tab-btn {
        font-size: 11px;
        padding: 6px 12px;
    }
}
</style>
