                        <button class="cyber-button send-button" onclick="sendToChat(this)">发送到聊天</button>
                    </div>
                </div>
            </div>

            <!-- 帖子1 -->
            <div class="post-item" onclick="togglePost(this)">
                <div class="post-header-info">
                    <div class="post-title">$1</div>
                    <div class="post-heat">🔥 $2</div>
